#!/usr/bin/env python3
"""Replace all 10 modern era events in data-5.js with enriched, verified versions."""
import re, sys

path = 'data-5.js'
with open(path, 'r', encoding='utf-8') as f:
    content = f.read()

eras_part5_start = content.index('const eras_part5 = [')
segment = content[eras_part5_start:]

def find_events_indices(text):
    """Find start indices of all event objects {name:'eventName',desc:... in text."""
    indices = []
    pattern = re.compile(r"\{name:'([^']+)',desc:'")
    for m in pattern.finditer(text):
        indices.append((m.start(), m.group(1)))
    return indices

def find_matching_brace(text, start_idx):
    """Find the closing } of the object starting at start_idx."""
    depth = 0
    in_string = False
    string_char = None
    i = start_idx
    while i < len(text):
        c = text[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            if c == string_char:
                in_string = False
            i += 1
            continue
        if c in "'\"":
            in_string = True
            string_char = c
            i += 1
            continue
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1

events = find_events_indices(segment)
print(f"Found {len(events)} events in data-5.js")

# The modern events are events 19-28 (0-indexed: 18-27)
# Ming: 0-7, Qing: 8-17, Modern: 18-27
modern_indices = events[18:28]
for idx, (pos, name) in enumerate(modern_indices):
    print(f"  Modern event {idx}: {name} at offset {pos}")

