# Now replace each event
for name, new_event in improvements.items():
    # Find the event in segment
    pattern = re.compile(r"\{name:'" + re.escape(name) + r"',desc:'")
    m = pattern.search(segment)
    if not m:
        print(f"ERROR: Could not find event '{name}'")
        continue
    start = m.start()
    end = find_matching_brace(segment, start)
    if end == -1:
        print(f"ERROR: Could not find closing brace for '{name}'")
        continue
    old = segment[start:end+1]
    new = new_event.strip()
    segment = segment[:start] + new + segment[end+1:]
    print(f"Replaced: {name}")

# Write back
content = content[:eras_part5_start] + segment

